fn is_sorted(a: &[i32]) -> bool {
    // Iterate through each adjacent pair in the slice.
    // If we ever find a[i] > a[i+1], we know it's not nondecreasing.
    for i in 1..a.len() {
        if a[i - 1] > a[i] {
            return false;
        }
    }
    // If we never found a violation, the slice is sorted.
    true
}

